consumedContracts.interfaceSketch:
type ReviewDimension = 'adherence' | 'conventions' | 'coverage' | 'quality';

interface CodeReviewSubject {
  readonly repoPath: string;
  readonly epicHash: string;
  readonly storyId: string;
  readonly changedFiles: readonly string[];
  readonly approvedLld: LldArtifact;
  readonly approvedPlan: PlanArtifact;
  readonly buildRecord: BuildArtifact;
}

interface ChangedSymbolSummary {
  readonly entityId: string;
  readonly file: string;
  readonly kind: string;
  readonly name: string;
  readonly signature: string;
  readonly callers: readonly string[];
  readonly callees: readonly string[];
  readonly testsReaching: readonly string[];
}

interface CodeReviewGrounding {
  readonly symbols: readonly ChangedSymbolSummary[];
}

interface DimensionFinding {
  readonly dimension: ReviewDimension;
  readonly severity: Severity;
  readonly location: string;
  readonly message: string;
  readonly expectationRef?: string;
  readonly counterpartRef?: string;
  readonly confidence?: 'observation' | 'breach';
}

interface DimensionResult {
  readonly dimension: ReviewDimension;
  readonly findings: readonly DimensionFinding[];
}
